// Streaming rows over slices of n money values: 8*n or 16*n bytes each.
func benchMem64(b *testing.B, n int) {
	a, c := make([]decimal64, n), make([]decimal64, n)
	q := make([]decimal64, n)
	for i := range a {
		a[i] = money64[i&7]
		q[i] = rates64[(i*5)&7]
	}
	tag := fmt.Sprintf("/64/n=%d", n)
	b.Run("Sum"+tag, func(b *testing.B) {
		b.SetBytes(int64(n) * 64 / 8)
		var s decimal64
		for range b.N {
			s = 0
			for _, v := range a {
				s += v
			}
		}
		sink64 = s
	})
	b.Run("MulQuant"+tag, func(b *testing.B) {
		b.SetBytes(3 * int64(n) * 64 / 8)
		for range b.N {
			for i := range a {
				c[i] = decimal.Quantize(a[i]*q[i], cent64)
			}
		}
	})
	b.Run("Max"+tag, func(b *testing.B) {
		b.SetBytes(int64(n) * 64 / 8)
		var s decimal64
		for range b.N {
			s = a[0]
			for _, v := range a {
				if v > s {
					s = v
				}
			}
		}
		sink64 = s
	})
}

// Sort of n d16 values (copy restored each iteration, time includes copy).
func benchSort64(b *testing.B, n int) {
	xs, _ := pool64(n, 7)
	w := make([]decimal64, n)
	b.Run(fmt.Sprintf("Sort/64/n=%d", n), func(b *testing.B) {
		for range b.N {
			copy(w, xs)
			slices.SortFunc(w, func(x, y decimal64) int {
				if x < y {
					return -1
				}
				if x > y {
					return 1
				}
				return 0
			})
		}
	})
}

// Gather: sum of table[idx[i]] for 1M random indices into a table of n values,
// so the table's footprint (8*n or 16*n bytes) decides which cache level holds it.
func benchGather64(b *testing.B, n int, idx []int32) {
	t := make([]decimal64, n)
	for i := range t {
		t[i] = money64[i&7]
	}
	b.Run(fmt.Sprintf("Gather/64/n=%d", n), func(b *testing.B) {
		var s decimal64
		for range b.N {
			s = 0
			for _, j := range idx {
				s += t[j]
			}
		}
		sink64 = s
	})
}

// cents pool: amounts of 3..10 digits at exponent -2 (0.01 .. 99,999,999.99),
// one in ten negative, and rates of 1..5 digits at exponent -4 (0.0001 .. 9.9999).
func centsPool64(n int, seed uint64) (xs, ys, rates []decimal64) { return centsPoolNeg64(n, seed, 10) }

func centsPoolNeg64(n int, seed uint64, negDen int) (xs, ys, rates []decimal64) {
	r := rand.New(rand.NewPCG(seed, 2))
	amt := func() decimal64 {
		nd := 3 + r.IntN(8)
		c := r.Int64N(pow10[nd]-pow10[nd-1]) + pow10[nd-1]
		return decimal.Compose[decimal64](negDen > 0 && r.IntN(negDen) == 0, 0, uint64(c), -2)
	}
	for range n {
		nd := 1 + r.IntN(5)
		c := r.Int64N(pow10[nd]-pow10[nd-1]) + pow10[nd-1]
		xs, ys = append(xs, amt()), append(ys, amt())
		rates = append(rates, decimal.Compose[decimal64](false, 0, uint64(c), -4))
	}
	return
}
